reserved_word:
-- Put the name in double quotes wherever it is used:
SELECT "{word}" FROM ...;
-- or rename it once (SQLite 3.25+):
ALTER TABLE {table} RENAME COLUMN "{word}" TO {word}_value;

check_violation:
-- The rule that failed: {constraint}
-- See the table's rules:
SELECT sql FROM sqlite_master WHERE type = 'table' AND name = '{table}';

fk_missing_parent:
-- This connection checks foreign keys (PRAGMA foreign_keys = ON). SQLite's message doesn't say which side failed:
-- adding/changing a child row -> its parent row must exist first; deleting/changing a parent -> child rows still point to it.
PRAGMA foreign_key_list({table});

fk_has_children:
-- Rows in another table still point to this one; find them:
PRAGMA foreign_key_check;
-- delete or move them first, or declare the link with ON DELETE CASCADE / SET NULL (a table rebuild in SQLite).

disk_full:
-- SQLite needs free space for the file AND its journal. Check the disk, and any page limit:
PRAGMA page_count;
PRAGMA max_page_count;

db_file_locked:
-- A transaction that reads and then writes: take the write lock at the start, and keep it short
BEGIN IMMEDIATE;
-- ... reads and writes ...
COMMIT;

alter_not_supported:
-- SQLite's ALTER TABLE can only RENAME TO, RENAME COLUMN, ADD COLUMN, DROP COLUMN (3.35+). Anything else is a rebuild:
PRAGMA foreign_keys = OFF;
BEGIN;
CREATE TABLE {table}_new (... the new definition ...);
INSERT INTO {table}_new (cols) SELECT cols FROM {table};
DROP TABLE {table};
ALTER TABLE {table}_new RENAME TO {table};
PRAGMA foreign_key_check;
COMMIT;
PRAGMA foreign_keys = ON;

-- 'non-constant default' (CURRENT_TIMESTAMP, an expression): add the column without it, then fill the old rows (preview first):
ALTER TABLE {table} ADD COLUMN created_at TEXT;
SELECT COUNT(*) FROM {table} WHERE created_at IS NULL;   -- the rows the next line changes
UPDATE {table} SET created_at = CURRENT_TIMESTAMP WHERE created_at IS NULL;

autoinc_not_integer_pk:
-- Only a column written exactly INTEGER PRIMARY KEY is the row id that numbers itself; AUTOINCREMENT goes after it:
CREATE TABLE t (id INTEGER PRIMARY KEY AUTOINCREMENT, ...);
-- Plain INTEGER PRIMARY KEY is usually enough (AUTOINCREMENT only stops ids of deleted rows coming back).

fk_target_not_key:
-- See what the parent's keys are:
SELECT name, pk FROM pragma_table_info('{parent}');
SELECT name, "unique" FROM pragma_index_list('{parent}');

two_primary_keys:
-- One PRIMARY KEY per table. Two columns that together name a row:
CREATE TABLE {table} (a INTEGER NOT NULL, b INTEGER NOT NULL, PRIMARY KEY (a, b));
-- A second column that must only be unique: UNIQUE instead of PRIMARY KEY.

drop_column_blocked:
-- DROP COLUMN refuses a column that an index, view, trigger, CHECK, foreign key or key still uses. See them:
SELECT type, name, sql FROM sqlite_master WHERE sql LIKE '%{column}%';
-- Drop (or change) those first, e.g. DROP INDEX ix_name; DROP VIEW v; then ALTER TABLE t DROP COLUMN {column};

txn_nested:
-- One transaction; the inner part as a savepoint
BEGIN;
-- ... outer work ...
SAVEPOINT inner_step;
-- ... inner work ...
RELEASE inner_step;     -- or ROLLBACK TO inner_step to undo only the inner part
COMMIT;

txn_not_active:
-- Start the transaction before the first change, end it once
BEGIN;
-- ... the changes ...
COMMIT;   -- or ROLLBACK;

savepoint_missing:
-- A savepoint is made inside the transaction, then released or rolled back to by the same name
BEGIN;
SAVEPOINT before_payment;
-- ...
ROLLBACK TO before_payment;
COMMIT;

outside_txn_only:
-- Outside the transaction: the journal mode before BEGIN, VACUUM after COMMIT
PRAGMA journal_mode = WAL;
BEGIN;
-- ... changes ...
COMMIT;
VACUUM;

read_upgrade_busy:
-- Take the write lock at the start (the busy timeout waits here), then read and write
PRAGMA busy_timeout = 5000;
BEGIN IMMEDIATE;
-- ... SELECT ... then UPDATE ...
COMMIT;

